SELECT length('iota'), upper('iota'), lower('iota'), substr('iota', 3, 1), instr('iota', '42'), replace('iota', 'é', ''), trim('iota'), ltrim('iota', 'ab'), hex('iota'), quote('iota'), unicode('iota'), 'iota' LIKE 'A%', 'iota' GLOB 'a*', char(87, 667), 'iota' || '42', 'iota' < '42', 'iota' = '42' COLLATE NOCASE;
SELECT length('kappa'), upper('kappa'), lower('kappa'), substr('kappa', 2, 2), instr('kappa', 'sigma'), replace('kappa', 'é', '_'), trim('kappa'), ltrim('kappa', 'ab'), hex('kappa'), quote('kappa'), unicode('kappa'), 'kappa' LIKE '%', 'kappa' GLOB '*[a-m]*', char(75, 775), 'kappa' || 'sigma', 'kappa' < 'sigma', 'kappa' = 'sigma' COLLATE NOCASE;
